import os, stat

base = 'data'
entries = []
for root, dirs, files in os.walk(base):
    for name in files:
        full = os.path.join(root, name)
        if stat.S_ISREG(os.lstat(full).st_mode):
            entries.append((os.path.relpath(full, base), full))
entries.sort()

total = 0
for rel, full in entries:
    try:
        with open(full, 'rb') as f:
            data = f.read()
    except OSError:
        print(f'{rel}: unreadable -> 0')
        continue
    n = sum(1 for line in data.split(b'\n') if b'invoice' in line)
    total += n
    print(f'{rel}: {n}')
print('TOTAL:', total)
PY","description":"Count lines containing invoice per file"}

