{"command":"cd /private/var/folders/w_/swqg2n117dzdrptxy6074cqw0000gp/T/w/8f940ae25a45 && python3 - <<'PY'
import os, stat, hashlib

base = 'data'
entries = []
for root, dirs, files in os.walk(base):
    for name in files:
        full = os.path.join(root, name)
        if stat.S_ISREG(os.lstat(full).st_mode):
            entries.append((os.path.relpath(full, base), full))
entries.sort()

lines = []
invoice_total = 0
for rel, full in entries:
    size = os.lstat(full).st_size
    try:
        h = hashlib.sha256()
        with open(full, 'rb') as f:
            while True:
                chunk = f.read(1 << 22)
                if not chunk:
                    break
                h.update(chunk)
        digest = h.hexdigest()[:12]
    except OSError:
        digest = 'unreadable'
    lines.append(f'{rel} | {size} | {digest}')

for rel, full in entries:
    try:
        with open(full, 'rb') as f:
            data = f.read()
    except OSError:
        continue
    invoice_total += sum(1 for ln in data.split(b'\n') if b'invoice' in ln)

lines.append(f'invoice_lines: {invoice_total}')
with open('INVENTORY.md', 'w', encoding='utf-8', newline='\n') as out:
    out.write('\n'.join(lines) + '\n')
print('written', len(lines), 'lines')
PY","description":"Generate INVENTORY.md"}

